import {
  getDatabase,
  ref as ref2,
  query,
  orderByChild,
  startAt,
  endAt,
  limitToLast,
  get as firebaseGet,
} from 'firebase/database';
import { withAdminDownloadToast } from 'utils/backendDownloadToast';

import { PAGE_SIZE, MAX_LOOKBACK_DAYS } from './constants';
import normalizeLastAction from '../utils/normalizeLastAction';
import { PROFILE_NODES } from '../utils/profileNodeSchema';

const get = (...args) =>
  withAdminDownloadToast(firebaseGet(...args), {
    operation: 'get',
    source: 'lastActionLoad',
    path: args[0],
  });

const LOOKBACK_BATCH_DAYS = 7;
const FILTER_CHUNK_SIZE = 40;

const toLastActionTimestamp = value => {
  const normalized = normalizeLastAction(value);
  if (normalized !== undefined) return normalized;
  const numeric = Number(value ?? 0);
  return Number.isFinite(numeric) ? numeric : 0;
};

const compareByLastActionDesc = ([, a], [, b]) =>
  toLastActionTimestamp(b?.lastAction) - toLastActionTimestamp(a?.lastAction);

// `lastAction` живе у `profileWorkflow` — там і питаємо. Раніше запит ішов у
// legacy `users`: екран показував те, що лежало в дзеркалі, а не те, що веб
// зберіг, і поле, оновлене у вебі, у видачу за датою не потрапляло.
//
// Віддаються ті самі пари `[id, дані]`: сам рядок робочого вузла тримає лише
// `lastAction`, а анкету поверх нього догідратовує `fetchUserById` — так само,
// як робив і з legacy-рядком.
export async function defaultFetchByLastActionRange(startTs, endTs, limit) {
  const db = getDatabase();
  const snapshot = await get(
    query(
      ref2(db, PROFILE_NODES.profileWorkflow),
      orderByChild('lastAction'),
      startAt(startTs),
      endAt(endTs),
      limitToLast(limit)
    )
  );

  if (!snapshot.exists()) return [];
  return Object.entries(snapshot.val());
}

export async function fetchUsersByLastActionPaged(
  startOffset = 0,
  limit = PAGE_SIZE,
  fetchRangeFn = defaultFetchByLastActionRange,
  fetchUserByIdFn,
  filterSettings = {},
  favoriteUsers = {},
  dislikedUsers = {},
  filterMainFnParam,
  onProgress
) {
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const target = startOffset + limit;
  const totalLimit = target + 1;

  let filterMainFn = filterMainFnParam;
  if (!fetchUserByIdFn || !filterMainFn) {
    const mod = await import('./config');
    if (!fetchUserByIdFn) fetchUserByIdFn = mod.fetchUserById;
    if (!filterMainFn) ({ filterMain: filterMainFn } = mod);
  }

  const combined = [];
  const filtered = [];
  let dayOffset = 0;
  let rawCursor = 0;
  const seenIds = new Set();

  while (filtered.length < target && dayOffset < MAX_LOOKBACK_DAYS) {
    const fetchLimit = Math.max(totalLimit - filtered.length, limit + 1);
    const batchDays = [];

    for (
      let i = 0;
      i < LOOKBACK_BATCH_DAYS && dayOffset + i < MAX_LOOKBACK_DAYS;
      i += 1
    ) {
      const day = new Date(today);
      day.setDate(today.getDate() - (dayOffset + i));
      const startTs = day.getTime();
      const endTs = startTs + 24 * 60 * 60 * 1000 - 1;
      batchDays.push({ startTs, endTs });
    }

    // eslint-disable-next-line no-await-in-loop
    const chunks = await Promise.all(
      batchDays.map(({ startTs, endTs }) =>
        fetchRangeFn(startTs, endTs, fetchLimit)
      )
    );

    const flattened = chunks.flat();
    const uniqueChunk = flattened.filter(([id]) => {
      if (seenIds.has(id)) return false;
      seenIds.add(id);
      return true;
    });

    if (uniqueChunk.length > 0) {
      const ids = uniqueChunk.map(([id]) => id);
      // eslint-disable-next-line no-await-in-loop
      const extras = await Promise.all(ids.map(id => fetchUserByIdFn(id)));
      const enriched = uniqueChunk.map(([id, data], idx) => {
        const extra = extras[idx];
        const combinedData = extra ? { ...data, ...extra } : data;
        return [id, { ...combinedData, userId: combinedData.userId || id }];
      });
      enriched.sort(compareByLastActionDesc);
      combined.push(...enriched);
      combined.sort(compareByLastActionDesc);
    }

    while (filtered.length < target && rawCursor < combined.length) {
      const chunk = combined.slice(rawCursor, rawCursor + FILTER_CHUNK_SIZE);
      rawCursor += FILTER_CHUNK_SIZE;
      const filteredChunk = filterMainFn(
        chunk,
        'LAST_ACTION',
        filterSettings,
        favoriteUsers,
        dislikedUsers
      );
      filtered.push(...filteredChunk);
    }

    if (onProgress) {
      const partial = filtered.slice(
        startOffset,
        Math.min(filtered.length, startOffset + limit)
      );
      const partUsers = {};
      partial.forEach(([pid, pdata]) => {
        partUsers[pid] = pdata;
      });
      onProgress(partUsers);
    }

    dayOffset += batchDays.length;
  }

  const slice = filtered.slice(startOffset, startOffset + limit);
  const users = {};
  slice.forEach(([id, data]) => {
    users[id] = data;
  });

  const nextOffset = startOffset + slice.length;
  const hasMore = filtered.length > startOffset + limit;

  return { users, lastKey: nextOffset, hasMore };
}
